def updateTokens(refresh_token):
    scopes = ['openid', 'profile', 'citiobs.secd.eu#create', 'citiobs.secd.eu#update', 'offline_access']
    redirect_uri = 'http://127.0.0.1:4711/SensorApp'
    (client_id, client_secret) = registerApp()
    state = ''.join(random.choice(string.ascii_letters) for m in range(10))

    service_information = ServiceInformation('https://www.authenix.eu/oauth/authorize',
                                             'https://www.authenix.eu/oauth/token',
                                             client_id,
                                             client_secret,
                                             scopes)
    manager = CredentialManager(service_information)
    manager.init_with_token(refresh_token)
    _logger.debug('Access Token = %s', manager._access_token)
    _logger.debug('Refresh Token = %s', manager.refresh_token)

    return manager._access_token, manager.refresh_token

def authorize():
    scopes = ['openid', 'profile', 'citiobs.secd.eu#create', 'citiobs.secd.eu#update', 'offline_access']
    redirect_uri = 'http://127.0.0.1:4711/SensorApp'
    (client_id, client_secret) = registerApp()
    state = ''.join(random.choice(string.ascii_letters) for m in range(10))

    service_information = ServiceInformation('https://www.authenix.eu/oauth/authorize',
                                             'https://www.authenix.eu/oauth/token',
                                             client_id,
                                             client_secret,
                                             scopes)
    manager = CredentialManager(service_information)

    code_verifier, code_challenge = generate_sha256_pkce(64)
    # Builds the authorization url and starts the local server according to the redirect_uri parameter
    kwargs = {'response_type': 'id_token code'}
    url = manager.init_authorize_code_process(redirect_uri,
                                         state,
                                         code_challenge=code_challenge,
                                         code_challenge_method="S256",
                                         **kwargs)
    _logger.info('Open this url in your browser\n%s', url)
    webbrowser.open(url, new=0, autoraise=True)

    code, id_token = manager.wait_and_terminate_authorize_code_process()

    _logger.debug('code got = %s', code)
    _logger.debug('id_token got = %s', id_token)
    kid = "www.authenix.eu#id_token"
    url = "https://www.authenix.eu/.well-known/jwks.json"
    jwks_client = PyJWKClient(url)
    signing_key = jwks_client.get_signing_key_from_jwt(id_token)
    data = jwt.decode(
        id_token,
        signing_key.key,
        algorithms=["RS256"],
        audience=client_id,
        options={"verify_exp": False, 'verify_iat': False},
    )
    _logger.info(data)
    manager.init_with_authorize_code(redirect_uri, code)
    _logger.debug('Access Token = %s', manager._access_token)
    _logger.debug('Refresh Token = %s', manager.refresh_token)

    return manager._access_token, manager.refresh_token, data

def refresh_mqtt_auth(client):
    """Refresh OAuth tokens and update MQTT username/password for the next connect."""
    userdata = client.user_data_get()
    access_token, refresh_token = updateTokens(userdata['refresh_token'])
    userdata['access_token'] = access_token
    userdata['refresh_token'] = refresh_token
    userdata['last_refresh'] = time.time()
    client.username_pw_set('Bearer', access_token)
    _logger.debug('MQTT credentials refreshed')
    return access_token, refresh_token

def connect_mqtt(token, refresh_token):
    def on_connect(client, userdata, flags, reason_code, properties):
        if reason_code == 0:
            print("Connected to MQTT Broker!")
        else:
            print("Failed to connect, return code %s" % reason_code)

    def on_disconnect(client, userdata, flags, reason_code, properties):
        print("Disconnected with result code: %s" % reason_code)
        if userdata.get('shutting_down'):
            return
        # Refresh credentials so paho's automatic reconnect uses a valid token.
        # Do not sleep or call reconnect() here — that blocks the network loop.
        try:
            refresh_mqtt_auth(client)
        except Exception as err:
            print("Failed to refresh MQTT token before reconnect: %s" % err)

    userdata = {
        'access_token': token,
        'refresh_token': refresh_token,
        'last_refresh': time.time(),
        'shutting_down': False,
    }
    client = mqtt_client.Client(
        callback_api_version=mqtt_client.CallbackAPIVersion.VERSION2,
        protocol=mqtt_client.MQTTv5,
        client_id=client_id,
        userdata=userdata,
        reconnect_on_failure=True,
    )
    client.reconnect_delay_set(min_delay=FIRST_RECONNECT_DELAY, max_delay=MAX_RECONNECT_DELAY)
    client.username_pw_set('Bearer', token)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.connect(broker, port)
    #client.connect('localhost', port)
    client.loop_start()
    return client


